<script setup lang="ts">
import MiniChrome from '../../components/MiniChrome.vue';
import {useViewport} from '../../composables/viewport';
const {styles:viewportStyles}=useViewport();
import {ref,computed} from 'vue';import {onLoad} from '@dcloudio/uni-app';import {getProduct,artworks,openArt} from '../../data/catalog';import {campaigns,getEditorial} from '../../data/editorial';import {openHome} from '../../stores/commerce';import PageHeader from '../../components/PageHeader.vue';import ProductVisual from '../../components/ProductVisual.vue';import ProductActions from '../../components/ProductActions.vue';import LineIcon from '../../components/LineIcon.vue';
const id=ref('gayo'),initialArt=ref<number>();onLoad(q=>{id.value=q?.id||'gayo';initialArt.value=q?.art?Number(q.art):undefined});const p=computed(()=>getProduct(id.value));const editorial=computed(()=>getEditorial(p.value));const campaign=computed(()=>campaigns.find(c=>c.id===p.value.id));const partner=computed(()=>p.value.category==='coffee'?'植造社':p.value.category==='bakery'?'烘焙伙伴':'服装伙伴');
function explore(){uni.pageScrollTo({selector:'#collaboration',duration:400})}
</script>
<template><view class="product-page screen" :style="viewportStyles"><MiniChrome/><PageHeader :label="p.name"/><view class="detail-chapter introduction"><view class="product-topline"><text>爱分你 × {{partner}}</text><text>01 / MEET THE PRODUCT</text></view><view class="product-hero"><image v-if="campaign" class="detail-campaign" :src="campaign.image" mode="aspectFit"/><ProductVisual v-else :product="p" large/></view><view class="product-info"><text class="section-kicker">{{p.en}}</text><text class="product-title">{{p.name}}</text><text class="product-slogan">{{p.slogan}}</text><view class="product-info-meta"><text>{{p.subtitle}}</text><text class="price-label">售价待公布</text></view><text class="body-text">{{p.description}}</text><button role="button" class="text-link" @click="explore">探索 8 款联名作品<LineIcon name="arrow" :size="20"/></button><text class="muted-note">包装与配图为概念展示，以正式商品为准。</text></view></view>
